121	export async function renewDomainAction(domainId: string): Promise<{ error?: string }> {
122	  const user = await requireUser();
123	  const domain = await db.domain.findUnique({ where: { id: domainId } });
124	  if (!domain || (domain.userId !== user.id && user.role !== "ADMIN")) return { error: "Not found." };
125	  const dTerm = domainTerm(domain.termYears);
126	  const renewCents = domainTermPriceCents(domain.priceCents, dTerm.years);
127	  const owner = await db.user.findUnique({ where: { id: domain.userId } });
128	  if (!owner || owner.balanceCents < renewCents) return { error: "Insufficient balance." };
129	
130	  try {
131	    await renewDomain(domain.name, dTerm.years, renewCents);
132	  } catch (e: any) {
133	    return { error: `Renewal failed: ${String(e?.message ?? e).slice(0, 200)}` };
134	  }
135	  await db.$transaction([
136	    db.user.update({ where: { id: domain.userId }, data: { balanceCents: { decrement: renewCents } } }),
137	    db.walletTransaction.create({
138	      data: { userId: domain.userId, amountCents: -renewCents, description: `Domain renewal: ${domain.name} (${dTerm.label})` },
139	    }),
140	    db.domain.update({
141	      where: { id: domainId },
142	      data: {
143	        expiresAt: new Date((domain.expiresAt ?? new Date()).getTime() + dTerm.years * 365 * 86400_000),
144	        status: "ACTIVE",
145	      },
146	    }),
147	  ]);
148	  revalidatePath(`/dashboard/domains/${domainId}`);
149	  return {};
150	}
