152	export async function toggleDomainAutoRenew(domainId: string) {
153	  const user = await requireUser();
154	  const domain = await db.domain.findUnique({ where: { id: domainId } });
155	  if (!domain || (domain.userId !== user.id && user.role !== "ADMIN")) throw new Error("Forbidden");
156	  await db.domain.update({ where: { id: domainId }, data: { autoRenew: !domain.autoRenew } });
157	  revalidatePath(`/dashboard/domains/${domainId}`);
158	}
