160	// ---------- DNS management ----------
161	
162	const RECORD_TYPES = ["A", "AAAA", "CNAME", "TXT", "MX", "NS", "SRV", "ALIAS"] as const;
163	
164	async function ownedDomain(domainId: string) {
165	  const user = await requireUser();
166	  const domain = await db.domain.findUnique({ where: { id: domainId } });
167	  if (!domain || (domain.userId !== user.id && user.role !== "ADMIN")) throw new Error("Forbidden");
168	  if (domain.status !== "ACTIVE") throw new Error("Domain is not active");
169	  return { user, domain };
170	}
171	
172	export async function addDnsRecord(prev: any, formData: FormData): Promise<{ error?: string }> {
173	  const domainId = String(formData.get("domainId") ?? "");
174	  let ctx;
175	  try {
176	    ctx = await ownedDomain(domainId);
177	  } catch (e: any) {
178	    return { error: e.message };
179	  }
180	  const parsed = z
181	    .object({
182	      name: z.string().max(120).default(""),
183	      type: z.enum(RECORD_TYPES),
184	      address: z.string().min(1).max(500),
185	      ttl: z.coerce.number().int().min(60).max(86400).default(300),
186	      mxPref: z.coerce.number().int().min(0).max(65535).optional(),
187	    })
188	    .safeParse({
189	      name: formData.get("name") ?? "",
190	      type: formData.get("type"),
191	      address: formData.get("address"),
192	      ttl: formData.get("ttl") || 300,
193	      mxPref: formData.get("mxPref") || undefined,
194	    });
195	  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid record." };
196	
197	  // "@" or blank => apex (name.com uses empty host for apex)
198	  const host = ["@", ""].includes(parsed.data.name.trim()) ? "" : parsed.data.name.trim();
199	  try {
200	    await addRecord(ctx.domain.name, {
201	      host,
202	      type: parsed.data.type,
203	      answer: parsed.data.address,
204	      ttl: parsed.data.ttl,
205	      priority: parsed.data.type === "MX" || parsed.data.type === "SRV" ? parsed.data.mxPref ?? 10 : undefined,
206	    });
207	  } catch (e: any) {
208	    return { error: String(e?.message ?? e).slice(0, 200) };
209	  }
210	  revalidatePath(`/dashboard/domains/${domainId}`);
211	  return {};
212	}
213	
214	export async function deleteDnsRecord(
215	  domainId: string,
216	  record: { name: string; type: string; address: string }
217	): Promise<{ error?: string }> {
218	  let ctx;
219	  try {
220	    ctx = await ownedDomain(domainId);
221	  } catch (e: any) {
222	    return { error: e.message };
223	  }
224	  const wantHost = ["@", ""].includes(record.name) ? "" : record.name;
225	  try {
226	    const recs = await listRecords(ctx.domain.name);
227	    const match = recs.find((r) => r.host === wantHost && r.type === record.type && r.answer === record.address);
228	    if (!match) return { error: "Record not found (it may have already been removed)." };
229	    await deleteRecord(ctx.domain.name, match.id);
230	  } catch (e: any) {
231	    return { error: String(e?.message ?? e).slice(0, 200) };
232	  }
233	  revalidatePath(`/dashboard/domains/${domainId}`);
234	  return {};
235	}
236	
237	/** One-click: point apex + www at the platform's public IP. */
238	export async function pointDomainAtServer(domainId: string): Promise<{ error?: string }> {
239	  let ctx;
240	  try {
241	    ctx = await ownedDomain(domainId);
242	  } catch (e: any) {
243	    return { error: e.message };
244	  }
245	  const ip = process.env.PUBLIC_IP;
246	  if (!ip) return { error: "Public IP not configured." };
247	  try {
248	    const recs = await listRecords(ctx.domain.name);
249	    for (const r of recs) {
250	      if (["", "www"].includes(r.host) && r.type === "A") await deleteRecord(ctx.domain.name, r.id);
251	    }
252	    await addRecord(ctx.domain.name, { host: "", type: "A", answer: ip, ttl: 300 });
253	    await addRecord(ctx.domain.name, { host: "www", type: "A", answer: ip, ttl: 300 });
254	  } catch (e: any) {
255	    return { error: String(e?.message ?? e).slice(0, 200) };
256	  }
257	  revalidatePath(`/dashboard/domains/${domainId}`);
258	  return {};
259	}
