51	export async function checkDomains(domains: string[]): Promise<DomainCheck[]> {
52	  const json = await nc("POST", "/v4/domains:checkAvailability", { domainNames: domains });
53	  return (json.results ?? []).map((r: any) => ({
54	    domain: r.domainName,
55	    available: r.purchasable === true,
56	    premium: r.premium === true,
57	    priceCents: dollarsToCents(r.purchasePrice),
58	    renewCents: dollarsToCents(r.renewalPrice ?? r.purchasePrice),
59	  }));
