"use client";

import { useEffect, useRef, useState } from "react";
import Link from "next/link";
import { fmtMoney } from "@/components/ui/primitives";

export type DomainCheckResult = {
  domain: string;
  available: boolean;
  premium: boolean;
  priceCents: number | null;
  renewCents: number | null;
};

const POPULAR_TLDS = [".com", ".net", ".io", ".dev", ".app", ".xyz"];

export function DomainSearch({ configured }: { configured: boolean }) {
  const [q, setQ] = useState("");
  const [results, setResults] = useState<DomainCheckResult[] | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    if (!configured) return;
    if (timer.current) clearTimeout(timer.current);
    const query = q.trim().toLowerCase();
    if (query.length < 2) {
      setResults(null);
      setLoading(false);
      setError(null);
      return;
    }
    setLoading(true);
    timer.current = setTimeout(async () => {
      try {
        const res = await fetch(`/api/domains/check?q=${encodeURIComponent(query)}`, {
          cache: "no-store",
        });
        const json: { results?: DomainCheckResult[]; error?: string } = await res.json();
        setError(json.error ?? null);
        setResults(json.results ?? []);
      } catch {
        setError("Search failed — try again.");
        setResults([]);
      }
      setLoading(false);
    }, 400);
    return () => {
      if (timer.current) clearTimeout(timer.current);
    };
  }, [q, configured]);

  return (
    <div className="card relative overflow-hidden bg-gradient-to-br from-navy-900/90 to-navy-850/70">
      <style>{`
        @keyframes domainResultIn {
          from { opacity: 0; transform: translateY(6px); }
          to { opacity: 1; transform: translateY(0); }
        }
      `}</style>
      <div className="glow-brand pointer-events-none absolute -right-24 -top-24 h-56 w-56 rounded-full bg-brand-500/20 blur-3xl" />

      <div className="relative">
        <div className="flex items-center gap-2">
          <span className="flex h-9 w-9 items-center justify-center rounded-xl border border-white/10 bg-gradient-to-br from-accent-blue/25 to-brand-500/25 text-brand-200">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6">
              <circle cx="12" cy="12" r="9" />
              <path d="M3 12h18M12 3a15 15 0 0 1 0 18M12 3a15 15 0 0 0 0 18" />
            </svg>
          </span>
          <div>
            <h2 className="text-lg font-semibold leading-tight">
              Find your <span className="grad-text">perfect domain</span>
            </h2>
            <p className="text-sm text-slate-400">
              Search .com, .net, .io, .dev and more — registered in seconds, paid from your wallet.
            </p>
          </div>
        </div>

        <div className="relative mt-4 max-w-xl">
          <input
            className="input py-3 pr-11 text-base"
            placeholder={configured ? "myproject.com" : "Domain search unavailable"}
            value={q}
            onChange={(e) => setQ(e.target.value)}
            disabled={!configured}
            autoComplete="off"
            spellCheck={false}
          />
          <span className="absolute right-3.5 top-1/2 -translate-y-1/2 text-slate-500">
            {loading ? (
              <span className="block h-4 w-4 animate-spin rounded-full border-2 border-slate-500 border-t-brand-400" />
            ) : (
              <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <circle cx="11" cy="11" r="7" />
                <path d="m20 20-3.5-3.5" />
              </svg>
            )}
          </span>
        </div>

        {configured && results === null && !loading && (
          <div className="mt-3 flex flex-wrap items-center gap-2">
            <span className="text-xs text-slate-500">Popular:</span>
            {POPULAR_TLDS.map((t) => (
              <span
                key={t}
                className="rounded-full border border-white/10 bg-white/[0.04] px-2.5 py-0.5 font-mono text-xs text-slate-400"
              >
                {t}
              </span>
            ))}
          </div>
        )}

        {!configured && (
          <div className="mt-4 max-w-xl rounded-xl border border-amber-500/30 bg-amber-500/10 px-4 py-3 text-sm text-amber-300">
            Domain registration activates once the registrar integration is configured. You can still
            manage domains already on your account.
          </div>
        )}

        {error && <p className="mt-3 text-sm text-red-400">{error}</p>}

        {results !== null && !loading && (
          <ul className="mt-4 max-w-xl divide-y divide-white/[0.05] overflow-hidden rounded-xl border border-white/[0.06] bg-navy-900/60">
            {results.length === 0 && !error && (
              <li className="px-4 py-3 text-sm text-slate-400">No supported TLDs match that search.</li>
            )}
            {results.map((r, i) => (
              <li
                key={r.domain}
                className="flex items-center justify-between gap-3 px-4 py-3"
                style={{ animation: `domainResultIn 0.28s ease both`, animationDelay: `${i * 45}ms` }}
              >
                <span className="flex items-center gap-2 font-mono text-sm">
                  <span
                    className={`h-1.5 w-1.5 rounded-full ${
                      r.available && !r.premium ? "bg-emerald-400" : r.premium ? "bg-amber-400" : "bg-slate-600"
                    }`}
                  />
                  {r.domain}
                </span>
                {r.premium ? (
                  <span className="flex items-center gap-3">
                    <span className="rounded-full border border-amber-500/40 bg-amber-500/10 px-2 py-0.5 text-[10px] font-semibold text-amber-300">
                      premium
                    </span>
                    <span className="text-xs text-slate-500">not supported</span>
                  </span>
                ) : r.available && r.priceCents !== null ? (
                  <span className="flex items-center gap-3">
                    <span className="text-right text-sm font-semibold text-emerald-400">
                      {fmtMoney(r.priceCents)}
                      <span className="text-xs font-normal text-slate-400">/yr</span>
                    </span>
                    <Link
                      href={`/dashboard/domains/register?domain=${encodeURIComponent(r.domain)}`}
                      className="btn-primary px-3 py-1 text-xs"
                    >
                      Register →
                    </Link>
                  </span>
                ) : (
                  <span className="rounded-full border border-white/10 bg-white/[0.04] px-2 py-0.5 text-xs text-slate-500">
                    taken
                  </span>
                )}
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

import Link from "next/link";
import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { registrarConfigured, getDnsHosts } from "@/lib/registrar";
import { PageHeader, StatCard, Badge, StatusDot, EmptyState, fmtMoney } from "@/components/ui/primitives";
import { DomainSearch } from "@/components/customer/DomainSearch";
import { DomainAutoRenewToggle } from "@/components/customer/DomainControls";

export const dynamic = "force-dynamic";

function daysUntil(d: Date): number {
  return Math.ceil((d.getTime() - Date.now()) / 86_400_000);
}

function expiryTone(days: number | null): "green" | "amber" | "red" | "slate" {
  if (days === null) return "slate";
  if (days < 0) return "red";
  if (days <= 30) return "amber";
  return "green";
}

function expiryLabel(d: Date | null): string {
  if (!d) return "—";
  const days = daysUntil(d);
  if (days < 0) return `expired ${-days}d ago`;
  if (days === 0) return "expires today";
  return `in ${days} day${days === 1 ? "" : "s"}`;
}

const statusDotFor = (s: string) =>
  s === "ACTIVE" ? "RUNNING" : s === "PENDING" ? "PENDING" : s === "EXPIRED" ? "SUSPENDED" : "ERROR";

export default async function DomainsPage() {
  const user = await requireUser();
  const configured = registrarConfigured();
  const domains = await db.domain.findMany({
    where: { userId: user.id },
    orderBy: { createdAt: "desc" },
  });

  // DNS record counts for active domains (best-effort — registrar may be briefly unavailable).
  const recordCounts = new Map<string, number | null>();
  if (configured) {
    await Promise.all(
      domains
        .filter((d) => d.status === "ACTIVE")
        .map(async (d) => {
          try {
            const hosts = await getDnsHosts(d.name);
            recordCounts.set(d.id, hosts.length);
          } catch {
            recordCounts.set(d.id, null);
          }
        })
    );
  }

  const active = domains.filter((d) => d.status === "ACTIVE").length;
  const expiringSoon = domains.filter(
    (d) => d.status === "ACTIVE" && d.expiresAt && daysUntil(d.expiresAt) <= 30 && daysUntil(d.expiresAt) >= 0
  ).length;

  return (
    <div className="space-y-6">
      <PageHeader title="Domains" sub="Register and manage domains, right next to your servers.">
        {configured && (
          <Link href="/dashboard/domains/register" className="btn-primary">
            Register a domain
          </Link>
        )}
      </PageHeader>

      <DomainSearch configured={configured} />

      {domains.length > 0 && (
        <div className="grid gap-4 sm:grid-cols-3">
          <StatCard
            label="Domains"
            value={String(domains.length)}
            icon={
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6">
                <circle cx="12" cy="12" r="9" />
                <path d="M3 12h18M12 3a15 15 0 0 1 0 18M12 3a15 15 0 0 0 0 18" />
              </svg>
            }
          />
          <StatCard
            label="Active"
            value={String(active)}
            delta={active === domains.length ? "all active" : `${domains.length - active} inactive`}
            deltaGood={active === domains.length}
          />
          <StatCard
            label="Expiring soon"
            value={String(expiringSoon)}
            delta={expiringSoon === 0 ? "nothing due" : "within 30 days"}
            deltaGood={expiringSoon === 0}
          />
        </div>
      )}

      {domains.length === 0 ? (
        <EmptyState
          title="No domains yet"
          sub={
            configured
              ? "Search above for an available name — you can register and point it at any of your servers in minutes."
              : "Domain registration lights up once the registrar integration is configured. Your registered domains will appear here."
          }
          action={
            configured ? (
              <Link href="/dashboard/domains/register" className="btn-primary">
                Register your first domain
              </Link>
            ) : undefined
          }
        />
      ) : (
        <div className="card p-0">
          <div className="flex items-center justify-between px-5 pt-5">
            <p className="section-label">Your domains</p>
            <span className="text-xs text-slate-500">{domains.length} total</span>
          </div>

          {/* Card grid on small screens, table on large */}
          <div className="grid gap-3 p-5 lg:hidden">
            {domains.map((d) => {
              const days = d.expiresAt ? daysUntil(d.expiresAt) : null;
              const count = recordCounts.get(d.id);
              return (
                <Link
                  key={d.id}
                  href={`/dashboard/domains/${d.id}`}
                  className="card card-hover block p-4"
                >
                  <div className="flex items-center justify-between gap-2">
                    <span className="truncate font-mono text-sm font-semibold text-slate-100">{d.name}</span>
                    <StatusDot status={statusDotFor(d.status)} label={d.status} />
                  </div>
                  <div className="mt-3 flex flex-wrap items-center gap-2 text-xs">
                    <Badge tone={expiryTone(days)}>{expiryLabel(d.expiresAt)}</Badge>
                    <Badge tone={d.autoRenew ? "green" : "slate"}>
                      auto-renew {d.autoRenew ? "on" : "off"}
                    </Badge>
                    {d.status === "ACTIVE" && (
                      <Badge tone="slate">{count === null || count === undefined ? "DNS —" : `${count} DNS`}</Badge>
                    )}
                    <span className="ml-auto text-slate-400">{fmtMoney(d.priceCents)}/yr</span>
                  </div>
                </Link>
              );
            })}
          </div>

          <div className="hidden overflow-x-auto lg:block">
            <table className="table-shell mt-2 min-w-[760px]">
              <thead>
                <tr>
                  <th>Domain</th>
                  <th>Status</th>
                  <th>Expires</th>
                  <th>DNS</th>
                  <th>Price</th>
                  <th>Auto-renew</th>
                  <th className="text-right">Actions</th>
                </tr>
              </thead>
              <tbody>
                {domains.map((d) => {
                  const days = d.expiresAt ? daysUntil(d.expiresAt) : null;
                  const count = recordCounts.get(d.id);
                  return (
                    <tr key={d.id}>
                      <td>
                        <Link
                          href={`/dashboard/domains/${d.id}`}
                          className="font-mono text-sm font-semibold text-slate-100 hover:text-brand-300"
                        >
                          {d.name}
                        </Link>
                      </td>
                      <td>
                        <StatusDot status={statusDotFor(d.status)} label={d.status} />
                      </td>
                      <td>
                        {d.expiresAt ? (
                          <div className="flex flex-col">
                            <span className="text-sm text-slate-300">
                              {d.expiresAt.toISOString().slice(0, 10)}
                            </span>
                            <span className={`text-xs ${expiryTone(days) === "amber" ? "text-amber-400" : expiryTone(days) === "red" ? "text-red-400" : "text-slate-500"}`}>
                              {expiryLabel(d.expiresAt)}
                            </span>
                          </div>
                        ) : (
                          <span className="text-slate-500">—</span>
                        )}
                      </td>
                      <td className="text-slate-400">
                        {d.status !== "ACTIVE"
                          ? "—"
                          : count === null || count === undefined
                            ? "—"
                            : `${count} record${count === 1 ? "" : "s"}`}
                      </td>
                      <td className="text-slate-400">{fmtMoney(d.priceCents)}/yr</td>
                      <td>
                        <DomainAutoRenewToggle domainId={d.id} autoRenew={d.autoRenew} />
                      </td>
                      <td className="text-right">
                        <Link href={`/dashboard/domains/${d.id}`} className="btn-secondary px-3 py-1 text-xs">
                          Manage
                        </Link>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useActionState, useEffect, useRef, useState } from "react";
import Link from "next/link";
import { purchaseDomain } from "@/lib/actions-domains";
import { DOMAIN_TERMS, domainTermPriceCents } from "@/lib/billing-terms";
import { fmtMoney } from "@/components/ui/primitives";
import type { DomainCheckResult } from "@/components/customer/DomainSearch";

const DOMAIN_RE = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.[a-z]{2,24}$/;
const PHONE_RE = /^\+\d{1,3}\.\d{4,14}$/;

const COUNTRIES: [string, string][] = [
  ["US", "United States"],
  ["CA", "Canada"],
  ["GB", "United Kingdom"],
  ["IE", "Ireland"],
  ["DE", "Germany"],
  ["FR", "France"],
  ["NL", "Netherlands"],
  ["BE", "Belgium"],
  ["ES", "Spain"],
  ["IT", "Italy"],
  ["PT", "Portugal"],
  ["SE", "Sweden"],
  ["NO", "Norway"],
  ["DK", "Denmark"],
  ["FI", "Finland"],
  ["PL", "Poland"],
  ["CH", "Switzerland"],
  ["AT", "Austria"],
  ["AU", "Australia"],
  ["NZ", "New Zealand"],
  ["JP", "Japan"],
  ["SG", "Singapore"],
  ["IN", "India"],
  ["BR", "Brazil"],
  ["MX", "Mexico"],
  ["ZA", "South Africa"],
];

const STEPS = ["Domain", "Term", "Contact", "Review"] as const;

type Contact = {
  firstName: string;
  lastName: string;
  address1: string;
  city: string;
  stateProvince: string;
  postalCode: string;
  country: string;
  phone: string;
  email: string;
};

function Stepper({ step }: { step: number }) {
  return (
    <div className="mb-6 flex flex-wrap items-center gap-2 text-xs">
      {STEPS.map((s, i) => (
        <div key={s} className="flex items-center gap-2">
          <span
            className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] font-semibold transition-colors ${
              i === step
                ? "border-brand-400 bg-brand-500/20 text-brand-200"
                : i < step
                  ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300"
                  : "border-white/10 text-slate-500"
            }`}
          >
            {i < step ? "✓" : i + 1}
          </span>
          <span className={i === step ? "text-white" : "text-slate-500"}>{s}</span>
          {i < STEPS.length - 1 && <span className="mx-1 text-slate-700">→</span>}
        </div>
      ))}
    </div>
  );
}

export function DomainRegisterWizard({
  initialDomain,
  initialCheck,
  defaultEmail,
  balanceCents,
}: {
  initialDomain: string;
  initialCheck: DomainCheckResult | null;
  defaultEmail: string;
  balanceCents: number;
}) {
  const [state, action, pending] = useActionState(purchaseDomain, {} as { error?: string });

  const [step, setStep] = useState(0);
  const [domain, setDomain] = useState(initialDomain);
  const [check, setCheck] = useState<DomainCheckResult | null>(initialCheck);
  const [checking, setChecking] = useState(false);
  const [checkError, setCheckError] = useState<string | null>(null);
  const [years, setYears] = useState(1);

  const [contact, setContact] = useState<Contact>({
    firstName: "",
    lastName: "",
    address1: "",
    city: "",
    stateProvince: "",
    postalCode: "",
    country: "US",
    phone: "",
    email: defaultEmail,
  });

  // Live search for changing the domain in step 1.
  const [q, setQ] = useState("");
  const [results, setResults] = useState<DomainCheckResult[] | null>(null);
  const [searching, setSearching] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    if (timer.current) clearTimeout(timer.current);
    const query = q.trim().toLowerCase();
    if (query.length < 2) {
      setResults(null);
      setSearching(false);
      return;
    }
    setSearching(true);
    timer.current = setTimeout(async () => {
      try {
        const res = await fetch(`/api/domains/check?q=${encodeURIComponent(query)}`, { cache: "no-store" });
        const json: { results?: DomainCheckResult[] } = await res.json();
        setResults(json.results ?? []);
      } catch {
        setResults([]);
      }
      setSearching(false);
    }, 400);
    return () => {
      if (timer.current) clearTimeout(timer.current);
    };
  }, [q]);

  async function recheck(name: string) {
    setChecking(true);
    setCheckError(null);
    try {
      const res = await fetch(`/api/domains/check?q=${encodeURIComponent(name)}`, { cache: "no-store" });
      const json: { results?: DomainCheckResult[]; error?: string } = await res.json();
      const match = (json.results ?? []).find((r) => r.domain === name) ?? null;
      setCheck(match);
      if (json.error) setCheckError(json.error);
      else if (!match) setCheckError("Could not check that domain — try another.");
    } catch {
      setCheckError("Availability check failed — try again.");
      setCheck(null);
    }
    setChecking(false);
  }

  function pickDomain(r: DomainCheckResult) {
    setDomain(r.domain);
    setCheck(r);
    setCheckError(null);
    setQ("");
    setResults(null);
  }

  const priceCents = check?.priceCents ?? null;
  const domainOk =
    DOMAIN_RE.test(domain) && !!check && check.available && !check.premium && priceCents !== null;
  const totalCents = priceCents !== null ? domainTermPriceCents(priceCents, years) : 0;
  const afterCents = balanceCents - totalCents;

  const contactValid =
    contact.firstName.trim().length > 0 &&
    contact.lastName.trim().length > 0 &&
    contact.address1.trim().length > 0 &&
    contact.city.trim().length > 0 &&
    contact.stateProvince.trim().length > 0 &&
    contact.postalCode.trim().length > 0 &&
    contact.country.length === 2 &&
    PHONE_RE.test(contact.phone) &&
    /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(contact.email);

  const term = DOMAIN_TERMS.find((t) => t.years === years) ?? DOMAIN_TERMS[0];
  const canContinue =
    (step === 0 && domainOk) || (step === 1) || (step === 2 && contactValid) || step === 3;
  const isLast = step === STEPS.length - 1;

  const set = (k: keyof Contact) => (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) =>
    setContact((c) => ({ ...c, [k]: e.target.value }));

  return (
    <div className="grid gap-6 lg:grid-cols-[1fr_320px]">
      <form action={action} className="card">
        {/* hidden fields submitted to purchaseDomain */}
        <input type="hidden" name="domain" value={domain} />
        <input type="hidden" name="years" value={years} />
        <input type="hidden" name="firstName" value={contact.firstName} />
        <input type="hidden" name="lastName" value={contact.lastName} />
        <input type="hidden" name="address1" value={contact.address1} />
        <input type="hidden" name="city" value={contact.city} />
        <input type="hidden" name="stateProvince" value={contact.stateProvince} />
        <input type="hidden" name="postalCode" value={contact.postalCode} />
        <input type="hidden" name="country" value={contact.country} />
        <input type="hidden" name="phone" value={contact.phone} />
        <input type="hidden" name="email" value={contact.email} />

        <Stepper step={step} />

        {state?.error && (
          <div className="mb-4 rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">
            {state.error}
          </div>
        )}

        {/* STEP 1 — DOMAIN */}
        {step === 0 && (
          <div>
            <h2 className="mb-1 font-semibold">Confirm your domain</h2>
            <p className="mb-4 text-sm text-slate-400">
              We&apos;ll re-check availability and pricing live before you commit.
            </p>

            <div
              className={`rounded-xl border p-4 ${
                domainOk
                  ? "border-emerald-500/30 bg-emerald-500/[0.06]"
                  : check && (check.premium || !check.available)
                    ? "border-amber-500/30 bg-amber-500/[0.06]"
                    : "border-white/10 bg-white/[0.02]"
              }`}
            >
              <div className="flex flex-wrap items-center justify-between gap-3">
                <span className="font-mono text-base font-semibold">{domain || "no domain selected"}</span>
                {checking ? (
                  <span className="flex items-center gap-2 text-xs text-slate-400">
                    <span className="block h-3.5 w-3.5 animate-spin rounded-full border-2 border-slate-500 border-t-brand-400" />
                    checking…
                  </span>
                ) : domainOk && priceCents !== null ? (
                  <span className="text-sm font-semibold text-emerald-400">
                    available · {fmtMoney(priceCents)}
                    <span className="text-xs font-normal text-slate-400">/yr</span>
                  </span>
                ) : check?.premium ? (
                  <span className="text-sm font-semibold text-amber-300">premium — not supported</span>
                ) : check && !check.available ? (
                  <span className="text-sm font-semibold text-amber-300">taken</span>
                ) : (
                  <span className="text-sm text-slate-500">not checked</span>
                )}
              </div>
              {check?.renewCents != null && domainOk && (
                <p className="mt-2 text-xs text-slate-500">
                  Renews at {fmtMoney(check.renewCents)}/yr after the initial term.
                </p>
              )}
              <button
                type="button"
                onClick={() => domain && recheck(domain)}
                disabled={!DOMAIN_RE.test(domain) || checking}
                className="btn-ghost mt-2 px-0 text-xs"
              >
                ↻ Re-check availability
              </button>
            </div>

            {checkError && <p className="mt-3 text-sm text-amber-300">{checkError}</p>}

            <div className="mt-5">
              <label className="label">Search for a different domain</label>
              <div className="relative max-w-md">
                <input
                  className="input pr-10"
                  placeholder="another-name.com"
                  value={q}
                  onChange={(e) => setQ(e.target.value)}
                  autoComplete="off"
                  spellCheck={false}
                />
                <span className="absolute right-3.5 top-1/2 -translate-y-1/2 text-slate-500">
                  {searching ? (
                    <span className="block h-4 w-4 animate-spin rounded-full border-2 border-slate-500 border-t-brand-400" />
                  ) : (
                    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                      <circle cx="11" cy="11" r="7" />
                      <path d="m20 20-3.5-3.5" />
                    </svg>
                  )}
                </span>
              </div>

              {results !== null && !searching && (
                <ul className="mt-3 max-w-md divide-y divide-white/[0.05] overflow-hidden rounded-xl border border-white/[0.06] bg-navy-900/60">
                  {results.length === 0 && (
                    <li className="px-4 py-3 text-sm text-slate-400">No supported TLDs match that search.</li>
                  )}
                  {results.map((r) => (
                    <li key={r.domain} className="flex items-center justify-between gap-3 px-4 py-2.5">
                      <span className="font-mono text-sm">{r.domain}</span>
                      {r.available && !r.premium && r.priceCents !== null ? (
                        <span className="flex items-center gap-3">
                          <span className="text-sm font-semibold text-emerald-400">{fmtMoney(r.priceCents)}</span>
                          <button
                            type="button"
                            onClick={() => pickDomain(r)}
                            className="btn-secondary px-3 py-1 text-xs"
                          >
                            Choose
                          </button>
                        </span>
                      ) : r.premium ? (
                        <span className="text-xs text-amber-300">premium</span>
                      ) : (
                        <span className="text-xs text-slate-500">taken</span>
                      )}
                    </li>
                  ))}
                </ul>
              )}
            </div>
          </div>
        )}

        {/* STEP 2 — TERM */}
        {step === 1 && (
          <div>
            <h2 className="mb-1 font-semibold">Choose your registration term</h2>
            <p className="mb-4 text-sm text-slate-400">Commit longer, save more — WHOIS privacy is always included.</p>
            <div className="grid gap-3 sm:grid-cols-3">
              {DOMAIN_TERMS.map((t) => {
                const total = priceCents !== null ? domainTermPriceCents(priceCents, t.years) : 0;
                const perYear = t.years > 0 ? Math.round(total / t.years) : total;
                const on = years === t.years;
                return (
                  <button
                    type="button"
                    key={t.years}
                    onClick={() => setYears(t.years)}
                    className={`card relative p-4 text-left transition ${
                      on ? "!border-brand-400 ring-1 ring-brand-400" : "hover:border-white/20"
                    }`}
                  >
                    {t.discountPct > 0 && (
                      <span className="absolute right-2 top-2 rounded-full bg-emerald-500/20 px-1.5 py-0.5 text-[10px] font-semibold text-emerald-300">
                        −{t.discountPct}%
                      </span>
                    )}
                    <p className="text-sm font-semibold">{t.label}</p>
                    <p className="mt-1 text-xl font-bold">
                      {fmtMoney(perYear)}
                      <span className="text-xs font-normal text-slate-400">/yr</span>
                    </p>
                    <p className="mt-0.5 text-[11px] text-slate-500">
                      {fmtMoney(total)} total{t.discountPct > 0 ? ` · save ${t.discountPct}%` : ""}
                    </p>
                  </button>
                );
              })}
            </div>
            <div className="mt-5 flex items-center justify-between rounded-xl border border-white/10 bg-white/[0.02] px-4 py-3 text-sm">
              <span className="text-slate-400">
                {domain} · {term.label}
              </span>
              <span className="font-semibold">{fmtMoney(totalCents)} total</span>
            </div>
          </div>
        )}

        {/* STEP 3 — CONTACT */}
        {step === 2 && (
          <div>
            <h2 className="mb-1 font-semibold">Registrant contact</h2>
            <p className="mb-4 text-sm text-slate-400">
              ICANN requires accurate contact details. These stay private — WHOIS privacy is included free.
            </p>
            <div className="grid gap-4 sm:grid-cols-2">
              <div>
                <label className="label">First name</label>
                <input className="input" value={contact.firstName} onChange={set("firstName")} maxLength={60} />
              </div>
              <div>
                <label className="label">Last name</label>
                <input className="input" value={contact.lastName} onChange={set("lastName")} maxLength={60} />
              </div>
              <div className="sm:col-span-2">
                <label className="label">Street address</label>
                <input
                  className="input"
                  value={contact.address1}
                  onChange={set("address1")}
                  maxLength={120}
                  placeholder="123 Main St"
                />
              </div>
              <div>
                <label className="label">City</label>
                <input className="input" value={contact.city} onChange={set("city")} maxLength={60} />
              </div>
              <div>
                <label className="label">State / Province</label>
                <input
                  className="input"
                  value={contact.stateProvince}
                  onChange={set("stateProvince")}
                  maxLength={60}
                />
              </div>
              <div>
                <label className="label">Postal code</label>
                <input className="input" value={contact.postalCode} onChange={set("postalCode")} maxLength={20} />
              </div>
              <div>
                <label className="label">Country</label>
                <select className="input" value={contact.country} onChange={set("country")}>
                  {COUNTRIES.map(([code, name]) => (
                    <option key={code} value={code}>
                      {name}
                    </option>
                  ))}
                </select>
              </div>
              <div>
                <label className="label">Phone</label>
                <input
                  className="input"
                  value={contact.phone}
                  onChange={set("phone")}
                  placeholder="+1.5551234567"
                />
                <p className={`mt-1 text-xs ${contact.phone && !PHONE_RE.test(contact.phone) ? "text-red-400" : "text-slate-500"}`}>
                  Format: +1.5551234567 (country code, dot, number)
                </p>
              </div>
              <div className="sm:col-span-2">
                <label className="label">Email</label>
                <input className="input" type="email" value={contact.email} onChange={set("email")} />
              </div>
            </div>
            {!contactValid && (
              <p className="mt-4 text-xs text-slate-500">Fill every field (and a valid phone/email) to continue.</p>
            )}
          </div>
        )}

        {/* STEP 4 — REVIEW */}
        {step === 3 && (
          <div>
            <h2 className="mb-4 font-semibold">Review &amp; register</h2>
            <dl className="space-y-2.5 text-sm">
              <div className="flex items-center justify-between">
                <dt className="text-slate-400">Domain</dt>
                <dd className="font-mono">{domain}</dd>
              </div>
              <div className="flex items-center justify-between">
                <dt className="text-slate-400">Term</dt>
                <dd>
                  {term.label}
                  {term.discountPct > 0 && (
                    <span className="ml-2 rounded-full bg-emerald-500/20 px-1.5 py-0.5 text-[10px] font-semibold text-emerald-300">
                      −{term.discountPct}%
                    </span>
                  )}
                </dd>
              </div>
              <div className="flex items-center justify-between">
                <dt className="text-slate-400">Registrant</dt>
                <dd className="text-right">
                  {contact.firstName} {contact.lastName}
                </dd>
              </div>
              <div className="flex items-center justify-between">
                <dt className="text-slate-400">WHOIS privacy</dt>
                <dd className="text-emerald-400">Included free</dd>
              </div>
              <div className="divider" />
              <div className="flex items-center justify-between text-base font-semibold">
                <dt>Due today</dt>
                <dd>{fmtMoney(totalCents)}</dd>
              </div>
              <div className="flex items-center justify-between">
                <dt className="text-slate-400">Wallet balance</dt>
                <dd>{fmtMoney(balanceCents)}</dd>
              </div>
              <div className="flex items-center justify-between">
                <dt className="text-slate-400">Balance after</dt>
                <dd className={afterCents < 0 ? "font-semibold text-red-400" : "text-emerald-400"}>
                  {fmtMoney(afterCents)}
                </dd>
              </div>
            </dl>

            {afterCents < 0 && (
              <div className="mt-4 rounded-xl border border-amber-500/30 bg-amber-500/10 px-4 py-3 text-sm text-amber-300">
                Insufficient balance.{" "}
                <Link href="/dashboard/billing" className="font-semibold underline">
                  Add funds
                </Link>{" "}
                before registering.
              </div>
            )}

            <p className="mt-4 text-xs text-slate-500">
              The fee is charged from your wallet. If registration fails for any reason, you are
              refunded automatically.
            </p>
          </div>
        )}

        {/* NAV */}
        <div className="mt-6 flex items-center justify-between">
          <button
            type="button"
            className="btn-ghost"
            disabled={step === 0}
            onClick={() => setStep((s) => Math.max(0, s - 1))}
          >
            ← Back
          </button>
          {!isLast ? (
            <button
              type="button"
              className="btn-primary"
              disabled={!canContinue}
              onClick={() => setStep((s) => s + 1)}
            >
              Continue →
            </button>
          ) : (
            <button className="btn-primary px-6" disabled={pending || !domainOk || afterCents < 0}>
              {pending ? "Registering…" : `Register — ${fmtMoney(totalCents)}`}
            </button>
          )}
        </div>
      </form>

      {/* SUMMARY ASIDE */}
      <aside className="space-y-4">
        <div className="card">
          <p className="section-label mb-3">Order summary</p>
          <dl className="space-y-2.5 text-sm">
            <div className="flex justify-between gap-2">
              <dt className="text-slate-400">Domain</dt>
              <dd className="truncate font-mono">{domain || "—"}</dd>
            </div>
            <div className="flex justify-between">
              <dt className="text-slate-400">Per year</dt>
              <dd>{priceCents !== null ? `${fmtMoney(priceCents)}` : "—"}</dd>
            </div>
            <div className="flex justify-between">
              <dt className="text-slate-400">Term</dt>
              <dd>{term.label}</dd>
            </div>
            <div className="flex justify-between">
              <dt className="text-slate-400">WHOIS privacy</dt>
              <dd className="text-emerald-400">Included</dd>
            </div>
            <div className="divider" />
            <div className="flex justify-between text-base font-semibold">
              <dt>Due today</dt>
              <dd>{fmtMoney(totalCents)}</dd>
            </div>
          </dl>
        </div>
        <p className="text-xs text-slate-500">
          Registration is charged from your wallet balance. Failed registrations are refunded
          automatically — you&apos;re never charged for a name you don&apos;t get.
        </p>
      </aside>
    </div>
  );
}

import Link from "next/link";
import { requireUser } from "@/lib/auth";
import { registrarConfigured, checkDomains, type DomainCheck } from "@/lib/registrar";
import { PageHeader, EmptyState } from "@/components/ui/primitives";
import { DomainRegisterWizard } from "@/components/customer/DomainRegisterWizard";

export const dynamic = "force-dynamic";

const DOMAIN_RE = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.[a-z]{2,24}$/;

export default async function RegisterDomainPage({
  searchParams,
}: {
  searchParams: Promise<{ domain?: string }>;
}) {
  const user = await requireUser();
  const { domain: raw } = await searchParams;
  const domain = (raw ?? "").toLowerCase().trim();
  const valid = DOMAIN_RE.test(domain);
  const configured = registrarConfigured();

  if (!configured) {
    return (
      <div className="space-y-6">
        <PageHeader title="Register domain" />
        <EmptyState
          title="Domain registration is not available yet"
          sub="Registration activates once the registrar integration is configured. Your existing domains stay manageable in the meantime."
          action={
            <Link href="/dashboard/domains" className="btn-primary">
              Back to domains
            </Link>
          }
        />
      </div>
    );
  }

  // Live availability + price for the pre-selected domain (best-effort).
  let initialCheck: DomainCheck | null = null;
  if (valid) {
    try {
      const [check] = await checkDomains([domain]);
      initialCheck = check ?? null;
    } catch {
      /* registrar briefly unreachable — the wizard can re-check client-side */
    }
  }

  return (
    <div className="space-y-6">
      <PageHeader title="Register domain" sub="A few quick steps to secure your name.">
        <Link href="/dashboard/domains" className="btn-ghost">
          ← All domains
        </Link>
      </PageHeader>

      <DomainRegisterWizard
        initialDomain={valid ? domain : ""}
        initialCheck={initialCheck}
        defaultEmail={user.email}
        balanceCents={user.balanceCents}
      />
    </div>
  );
}

"use client";

import { useActionState, useState, useTransition } from "react";
import {
  renewDomainAction,
  toggleDomainAutoRenew,
  addDnsRecord,
  deleteDnsRecord,
  pointDomainAtServer,
} from "@/lib/actions-domains";
import { domainTerm, domainTermPriceCents } from "@/lib/billing-terms";
import { fmtMoney } from "@/components/ui/primitives";

export function DomainAutoRenewToggle({
  domainId,
  autoRenew,
}: {
  domainId: string;
  autoRenew: boolean;
}) {
  const [pending, start] = useTransition();
  return (
    <button
      type="button"
      disabled={pending}
      onClick={() => start(() => toggleDomainAutoRenew(domainId))}
      title={autoRenew ? "Auto-renew is on — click to turn off" : "Auto-renew is off — click to turn on"}
      className={`relative h-5 w-9 cursor-pointer rounded-full transition-colors disabled:opacity-50 ${
        autoRenew ? "bg-gradient-to-r from-accent-blue to-brand-500" : "bg-white/10"
      }`}
    >
      <span
        className={`absolute top-0.5 h-4 w-4 rounded-full bg-white transition-all ${
          autoRenew ? "left-[18px]" : "left-0.5"
        }`}
      />
    </button>
  );
}

export function RenewDomainButton({
  domainId,
  priceCents,
  termYears,
}: {
  domainId: string;
  priceCents: number;
  termYears: number;
}) {
  const [pending, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const term = domainTerm(termYears);
  const total = domainTermPriceCents(priceCents, term.years);
  return (
    <div>
      <button
        className="btn-primary w-full"
        disabled={pending}
        onClick={() => {
          if (!window.confirm(`Renew this domain for ${term.label} (${fmtMoney(total)})?`)) return;
          start(async () => {
            setError(null);
            const res = await renewDomainAction(domainId);
            if (res?.error) setError(res.error);
          });
        }}
      >
        {pending ? "Renewing…" : `Renew now (+${term.label}, ${fmtMoney(total)})`}
      </button>
      {error && <p className="mt-2 text-sm text-red-400">{error}</p>}
    </div>
  );
}

export function PointAtServerButton({ domainId, ip }: { domainId: string; ip: string }) {
  const [pending, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const [done, setDone] = useState(false);
  return (
    <div>
      <button
        className="btn-secondary"
        disabled={pending}
        onClick={() => {
          if (
            !window.confirm(
              `Point @ and www at ${ip}? Existing A records for @ and www will be replaced.`
            )
          )
            return;
          start(async () => {
            setError(null);
            setDone(false);
            const res = await pointDomainAtServer(domainId);
            if (res?.error) setError(res.error);
            else setDone(true);
          });
        }}
      >
        {pending ? "Updating DNS…" : "Point at my server"}
      </button>
      {done && (
        <p className="mt-2 text-sm text-emerald-400">
          DNS updated — propagation can take up to an hour.
        </p>
      )}
      {error && <p className="mt-2 text-sm text-red-400">{error}</p>}
    </div>
  );
}

const DNS_TYPES = ["A", "AAAA", "CNAME", "TXT", "MX", "NS", "SRV"] as const;
const TTL_PRESETS = [
  [300, "5 min"],
  [1800, "30 min"],
  [3600, "1 hour"],
  [14400, "4 hours"],
  [86400, "1 day"],
] as const;

const placeholders: Record<string, string> = {
  A: "203.0.113.10",
  AAAA: "2001:db8::1",
  CNAME: "target.example.com",
  TXT: "v=spf1 include:_spf.example.com ~all",
  MX: "mail.example.com",
  NS: "ns1.example.com",
  SRV: "10 5 5060 sip.example.com",
};

const hints: Record<string, string> = {
  A: "Points a name at an IPv4 address.",
  AAAA: "Points a name at an IPv6 address.",
  CNAME: "Aliases this name to another hostname.",
  TXT: "Free-form text — SPF, DKIM, domain verification.",
  MX: "Mail server for the domain. Lower priority wins.",
  NS: "Delegates a subdomain to other nameservers.",
  SRV: "Service record: weight port target.",
};

export function DnsAddForm({ domainId }: { domainId: string }) {
  const [state, action, pending] = useActionState(addDnsRecord, {} as { error?: string });
  const [type, setType] = useState<string>("A");
  const needsPriority = type === "MX" || type === "SRV";

  return (
    <form action={action} className="space-y-4">
      <input type="hidden" name="domainId" value={domainId} />
      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
        <div>
          <label className="label">Type</label>
          <select className="input" name="type" value={type} onChange={(e) => setType(e.target.value)}>
            {DNS_TYPES.map((t) => (
              <option key={t} value={t}>
                {t}
              </option>
            ))}
          </select>
        </div>
        <div>
          <label className="label">Name</label>
          <input className="input" name="name" placeholder="@ or www" autoComplete="off" spellCheck={false} />
        </div>
        <div className={needsPriority ? "" : "lg:col-span-2"}>
          <label className="label">Value</label>
          <input
            className="input font-mono text-xs"
            name="address"
            placeholder={placeholders[type] ?? "value"}
            required
            autoComplete="off"
            spellCheck={false}
          />
        </div>
        {needsPriority && (
          <div>
            <label className="label">Priority</label>
            <input className="input" name="mxPref" type="number" min={0} max={65535} defaultValue={10} />
          </div>
        )}
        <div>
          <label className="label">TTL</label>
          <select className="input" name="ttl" defaultValue={1800}>
            {TTL_PRESETS.map(([v, label]) => (
              <option key={v} value={v}>
                {label}
              </option>
            ))}
          </select>
        </div>
      </div>

      <div className="flex flex-wrap items-center justify-between gap-3">
        <p className="text-xs text-slate-500">{hints[type]}</p>
        <button className="btn-primary" disabled={pending}>
          {pending ? "Adding…" : "Add record"}
        </button>
      </div>
      {state?.error && (
        <div className="rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">
          {state.error}
        </div>
      )}
    </form>
  );
}

export function DnsDeleteButton({
  domainId,
  record,
}: {
  domainId: string;
  record: { name: string; type: string; address: string };
}) {
  const [pending, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  return (
    <span className="inline-flex items-center gap-2">
      {error && <span className="text-xs text-red-400">{error}</span>}
      <button
        className="btn-danger px-2.5 py-1 text-xs"
        disabled={pending}
        title="Delete record"
        onClick={() => {
          if (!window.confirm(`Delete ${record.type} record "${record.name}"?`)) return;
          start(async () => {
            setError(null);
            const res = await deleteDnsRecord(domainId, record);
            if (res?.error) setError(res.error);
          });
        }}
      >
        {pending ? "…" : "Delete"}
      </button>
    </span>
  );
}

import { notFound } from "next/navigation";
import Link from "next/link";
import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { getDnsHosts, registrarConfigured, type DnsHost } from "@/lib/registrar";
import { domainTerm, domainTermPriceCents } from "@/lib/billing-terms";
import { PageHeader, StatusDot, Badge, fmtMoney } from "@/components/ui/primitives";
import { AutoRefresh } from "@/components/AutoRefresh";
import {
  DomainAutoRenewToggle,
  RenewDomainButton,
  PointAtServerButton,
  DnsAddForm,
  DnsDeleteButton,
} from "@/components/customer/DomainControls";

export const dynamic = "force-dynamic";

function daysUntil(d: Date): number {
  return Math.ceil((d.getTime() - Date.now()) / 86_400_000);
}

function expiryNote(d: Date | null): { text: string; tone: "green" | "amber" | "red" | "slate" } {
  if (!d) return { text: "—", tone: "slate" };
  const days = daysUntil(d);
  if (days < 0) return { text: `expired ${-days} days ago`, tone: "red" };
  if (days === 0) return { text: "expires today", tone: "red" };
  if (days <= 30) return { text: `in ${days} days`, tone: "amber" };
  return { text: `in ${days} days`, tone: "green" };
}

const typeTone: Record<string, "brand" | "green" | "amber" | "slate"> = {
  A: "green",
  AAAA: "green",
  CNAME: "brand",
  MX: "amber",
  TXT: "slate",
  NS: "brand",
  SRV: "slate",
};

export default async function DomainPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const user = await requireUser();
  const domain = await db.domain.findUnique({ where: { id } });
  if (!domain || (domain.userId !== user.id && user.role !== "ADMIN")) notFound();

  const publicIp = process.env.PUBLIC_IP ?? "";

  let dnsHosts: DnsHost[] | null = null;
  let dnsError: string | null = null;
  if (domain.status === "ACTIVE" && registrarConfigured()) {
    try {
      dnsHosts = await getDnsHosts(domain.name);
    } catch (e) {
      dnsError = String(e instanceof Error ? e.message : e).slice(0, 200);
    }
  }

  const statusDot =
    domain.status === "ACTIVE"
      ? "RUNNING"
      : domain.status === "PENDING"
        ? "PENDING"
        : domain.status === "EXPIRED"
          ? "SUSPENDED"
          : "ERROR";

  const term = domainTerm(domain.termYears);
  const renewTotal = domainTermPriceCents(domain.priceCents, term.years);
  const exp = expiryNote(domain.expiresAt);

  return (
    <div className="space-y-6">
      {domain.status === "PENDING" && <AutoRefresh />}
      <PageHeader title={domain.name} sub="Domain management">
        <Link href="/dashboard/domains" className="btn-ghost">
          ← All domains
        </Link>
      </PageHeader>

      {domain.status === "FAILED" && (
        <div className="card border-red-500/30 text-sm text-red-300">
          Registration failed{domain.error ? `: ${domain.error}` : "."} You were refunded — try
          again or contact support.
        </div>
      )}

      {domain.status === "PENDING" && (
        <div className="card border-amber-500/30 bg-amber-500/[0.06] text-sm text-amber-200">
          Registration is being processed with the registrar. This page refreshes automatically —
          it usually completes within a minute.
        </div>
      )}

      <div className="grid gap-6 lg:grid-cols-2">
        {/* Registration */}
        <div className="card">
          <div className="mb-4 flex items-center justify-between">
            <h2 className="font-semibold">Registration</h2>
            <StatusDot status={statusDot} label={domain.status} />
          </div>
          <dl className="space-y-3 text-sm">
            <div className="flex justify-between">
              <dt className="text-slate-400">Registered</dt>
              <dd>{domain.registeredAt ? domain.registeredAt.toISOString().slice(0, 10) : "—"}</dd>
            </div>
            <div className="flex items-center justify-between">
              <dt className="text-slate-400">Expires</dt>
              <dd className="flex items-center gap-2">
                <span>{domain.expiresAt ? domain.expiresAt.toISOString().slice(0, 10) : "—"}</span>
                {domain.expiresAt && <Badge tone={exp.tone}>{exp.text}</Badge>}
              </dd>
            </div>
            <div className="flex justify-between">
              <dt className="text-slate-400">Term</dt>
              <dd>{term.label}</dd>
            </div>
            <div className="flex justify-between">
              <dt className="text-slate-400">Renewal price</dt>
              <dd>
                {fmtMoney(renewTotal)}
                <span className="text-xs text-slate-500"> / {term.label}</span>
              </dd>
            </div>
            <div className="flex items-center justify-between">
              <dt className="text-slate-400">Auto-renew</dt>
              <dd className="flex items-center gap-2">
                <DomainAutoRenewToggle domainId={domain.id} autoRenew={domain.autoRenew} />
                <span className="text-xs text-slate-500">{domain.autoRenew ? "on" : "off"}</span>
              </dd>
            </div>
          </dl>
          {domain.status === "ACTIVE" && (
            <div className="mt-5">
              <RenewDomainButton
                domainId={domain.id}
                priceCents={domain.priceCents}
                termYears={domain.termYears}
              />
            </div>
          )}
        </div>

        {/* Point at server */}
        <div className="card">
          <h2 className="mb-3 font-semibold">Point at my server</h2>
          <p className="text-sm text-slate-400">
            One click sets <span className="font-mono text-brand-300">@</span> and{" "}
            <span className="font-mono text-brand-300">www</span> A records to your public server IP{" "}
            <span className="font-mono text-brand-300">{publicIp || "—"}</span>. Then add a port
            forward for your web server (80/443) on the server&apos;s Networking tab to serve traffic.
          </p>
          <div className="mt-4">
            {domain.status === "ACTIVE" ? (
              <PointAtServerButton domainId={domain.id} ip={publicIp} />
            ) : (
              <Badge tone="slate">available once the domain is active</Badge>
            )}
          </div>
          <div className="mt-5 rounded-xl border border-white/[0.06] bg-white/[0.02] p-3 text-xs text-slate-500">
            Prefer manual control? Use the DNS records manager below to add exactly the records you
            need.
          </div>
        </div>
      </div>

      {/* DNS records */}
      <div className="card p-0">
        <div className="flex flex-wrap items-center justify-between gap-2 px-5 pt-5">
          <div className="flex items-center gap-3">
            <p className="section-label">DNS records</p>
            {dnsHosts && <Badge tone="slate">{dnsHosts.length} total</Badge>}
          </div>
          <Badge tone="brand">name.com DNS</Badge>
        </div>

        {domain.status !== "ACTIVE" ? (
          <p className="px-5 py-6 text-sm text-slate-400">
            DNS management becomes available once the domain is active.
          </p>
        ) : dnsError ? (
          <div className="px-5 py-6">
            <div className="rounded-xl border border-amber-500/30 bg-amber-500/10 px-4 py-3">
              <p className="text-sm text-amber-300">Could not load DNS records: {dnsError}</p>
              <p className="mt-1 text-xs text-slate-500">
                The registrar API may be briefly unavailable — refresh to retry.
              </p>
            </div>
          </div>
        ) : dnsHosts && dnsHosts.length === 0 ? (
          <p className="px-5 py-6 text-sm text-slate-400">
            No records yet — add your first record below, or use “Point at my server”.
          </p>
        ) : dnsHosts ? (
          <div className="overflow-x-auto">
            <table className="table-shell mt-2 min-w-[620px]">
              <thead>
                <tr>
                  <th>Name</th>
                  <th>Type</th>
                  <th>Value</th>
                  <th>TTL</th>
                  <th className="text-right">Actions</th>
                </tr>
              </thead>
              <tbody>
                {dnsHosts.map((h, i) => (
                  <tr key={`${h.type}-${h.name}-${i}`}>
                    <td className="font-mono text-xs text-slate-200">{h.name}</td>
                    <td>
                      <Badge tone={typeTone[h.type] ?? "slate"}>{h.type}</Badge>
                      {(h.type === "MX" || h.type === "SRV") && h.mxPref !== undefined && (
                        <span className="ml-1.5 text-xs text-slate-500">prio {h.mxPref}</span>
                      )}
                    </td>
                    <td className="max-w-72 truncate font-mono text-xs text-slate-300" title={h.address}>
                      {h.address}
                    </td>
                    <td className="text-slate-400">{h.ttl}</td>
                    <td className="text-right">
                      <DnsDeleteButton
                        domainId={domain.id}
                        record={{ name: h.name, type: h.type, address: h.address }}
                      />
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ) : (
          <p className="px-5 py-6 text-sm text-slate-400">DNS is unavailable.</p>
        )}
      </div>

      {domain.status === "ACTIVE" && !dnsError && (
        <div className="card">
          <h2 className="mb-4 font-semibold">Add DNS record</h2>
          <DnsAddForm domainId={domain.id} />
        </div>
      )}
    </div>
  );
}
